package com.bank.dsa;

import java.math.BigDecimal;
import java.util.logging.*;

// Runnable demo: triangle-inequality-style balance check over three limits.
public class FormTriangleDemo {
    private static final Logger log = Logger.getLogger(FormTriangleDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TriangleValidator validator = new TriangleValidator();

        boolean ok = validator.canFormTriangle(
                new BigDecimal("3"), new BigDecimal("4"), new BigDecimal("5"));
        log.info(() -> "Limits 3,4,5 balanced? " + (ok ? "Yes" : "No"));

        boolean bad = validator.canFormTriangle(
                new BigDecimal("1"), new BigDecimal("2"), new BigDecimal("10"));
        log.warning(() -> "Limits 1,2,10 balanced? " + (bad ? "Yes" : "No"));
    }
}

// ─── Would be in TriangleValidator.java in a real project ───
class TriangleValidator {
    // Valid iff A+B>C AND B+C>A AND C+A>B (strict). compareTo for exact numeric comparison.
    boolean canFormTriangle(BigDecimal a, BigDecimal b, BigDecimal c) {
        if (a == null || b == null || c == null) {
            throw new IllegalArgumentException("Lengths must not be null");
        }
        if (a.signum() <= 0 || b.signum() <= 0 || c.signum() <= 0) {
            return false;  // non-positive length cannot be a side
        }
        boolean ab = a.add(b).compareTo(c) > 0;  // A + B > C
        boolean bc = b.add(c).compareTo(a) > 0;  // B + C > A
        boolean ca = c.add(a).compareTo(b) > 0;  // C + A > B
        return ab && bc && ca;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
